-- Preserve existing palette choices and raw hex values, then enforce opaque hex storage.
BEGIN;
UPDATE "Persona" SET color = CASE WHEN color IS NULL OR btrim(color) = '' THEN NULL WHEN lower(btrim(color)) = 'blue' THEN '#3b82f6' WHEN lower(btrim(color)) = 'purple' THEN '#8b5cf6' WHEN lower(btrim(color)) = 'pink' THEN '#ec4899' WHEN lower(btrim(color)) = 'rose' THEN '#f43f5e' WHEN lower(btrim(color)) = 'orange' THEN '#f97316' WHEN lower(btrim(color)) = 'amber' THEN '#f59e42' WHEN lower(btrim(color)) = 'green' THEN '#22c55e' WHEN lower(btrim(color)) = 'teal' THEN '#14b8a6' WHEN lower(btrim(color)) = 'cyan' THEN '#06b6d4' WHEN lower(btrim(color)) = 'indigo' THEN '#6366f1' WHEN lower(btrim(color)) = 'violet' THEN '#a21caf' WHEN lower(btrim(color)) = 'fuchsia' THEN '#d946ef' WHEN btrim(color) ~ '^#[0-9a-fA-F]{3}$' THEN lower('#' || substr(btrim(color),2,1) || substr(btrim(color),2,1) || substr(btrim(color),3,1) || substr(btrim(color),3,1) || substr(btrim(color),4,1) || substr(btrim(color),4,1)) ELSE lower(btrim(color)) END WHERE color IS NOT NULL;
ALTER TABLE "Persona" ADD CONSTRAINT "Persona_color_hex_check" CHECK (color IS NULL OR color ~ '^#[0-9a-f]{6}$');
UPDATE "Dimension" SET color = CASE WHEN color IS NULL OR btrim(color) = '' THEN NULL WHEN lower(btrim(color)) = 'blue' THEN '#3b82f6' WHEN lower(btrim(color)) = 'purple' THEN '#8b5cf6' WHEN lower(btrim(color)) = 'pink' THEN '#ec4899' WHEN lower(btrim(color)) = 'rose' THEN '#f43f5e' WHEN lower(btrim(color)) = 'orange' THEN '#f97316' WHEN lower(btrim(color)) = 'amber' THEN '#f59e42' WHEN lower(btrim(color)) = 'green' THEN '#22c55e' WHEN lower(btrim(color)) = 'teal' THEN '#14b8a6' WHEN lower(btrim(color)) = 'cyan' THEN '#06b6d4' WHEN lower(btrim(color)) = 'indigo' THEN '#6366f1' WHEN lower(btrim(color)) = 'violet' THEN '#a21caf' WHEN lower(btrim(color)) = 'fuchsia' THEN '#d946ef' WHEN btrim(color) ~ '^#[0-9a-fA-F]{3}$' THEN lower('#' || substr(btrim(color),2,1) || substr(btrim(color),2,1) || substr(btrim(color),3,1) || substr(btrim(color),3,1) || substr(btrim(color),4,1) || substr(btrim(color),4,1)) ELSE lower(btrim(color)) END WHERE color IS NOT NULL;
ALTER TABLE "Dimension" ADD CONSTRAINT "Dimension_color_hex_check" CHECK (color IS NULL OR color ~ '^#[0-9a-f]{6}$');
UPDATE "Archetype" SET color = CASE WHEN color IS NULL OR btrim(color) = '' THEN NULL WHEN lower(btrim(color)) = 'blue' THEN '#3b82f6' WHEN lower(btrim(color)) = 'purple' THEN '#8b5cf6' WHEN lower(btrim(color)) = 'pink' THEN '#ec4899' WHEN lower(btrim(color)) = 'rose' THEN '#f43f5e' WHEN lower(btrim(color)) = 'orange' THEN '#f97316' WHEN lower(btrim(color)) = 'amber' THEN '#f59e42' WHEN lower(btrim(color)) = 'green' THEN '#22c55e' WHEN lower(btrim(color)) = 'teal' THEN '#14b8a6' WHEN lower(btrim(color)) = 'cyan' THEN '#06b6d4' WHEN lower(btrim(color)) = 'indigo' THEN '#6366f1' WHEN lower(btrim(color)) = 'violet' THEN '#a21caf' WHEN lower(btrim(color)) = 'fuchsia' THEN '#d946ef' WHEN btrim(color) ~ '^#[0-9a-fA-F]{3}$' THEN lower('#' || substr(btrim(color),2,1) || substr(btrim(color),2,1) || substr(btrim(color),3,1) || substr(btrim(color),3,1) || substr(btrim(color),4,1) || substr(btrim(color),4,1)) ELSE lower(btrim(color)) END WHERE color IS NOT NULL;
ALTER TABLE "Archetype" ADD CONSTRAINT "Archetype_color_hex_check" CHECK (color IS NULL OR color ~ '^#[0-9a-f]{6}$');
UPDATE "QuizPage" SET color = CASE WHEN color IS NULL OR btrim(color) = '' THEN NULL WHEN lower(btrim(color)) = 'blue' THEN '#3b82f6' WHEN lower(btrim(color)) = 'purple' THEN '#8b5cf6' WHEN lower(btrim(color)) = 'pink' THEN '#ec4899' WHEN lower(btrim(color)) = 'rose' THEN '#f43f5e' WHEN lower(btrim(color)) = 'orange' THEN '#f97316' WHEN lower(btrim(color)) = 'amber' THEN '#f59e42' WHEN lower(btrim(color)) = 'green' THEN '#22c55e' WHEN lower(btrim(color)) = 'teal' THEN '#14b8a6' WHEN lower(btrim(color)) = 'cyan' THEN '#06b6d4' WHEN lower(btrim(color)) = 'indigo' THEN '#6366f1' WHEN lower(btrim(color)) = 'violet' THEN '#a21caf' WHEN lower(btrim(color)) = 'fuchsia' THEN '#d946ef' WHEN btrim(color) ~ '^#[0-9a-fA-F]{3}$' THEN lower('#' || substr(btrim(color),2,1) || substr(btrim(color),2,1) || substr(btrim(color),3,1) || substr(btrim(color),3,1) || substr(btrim(color),4,1) || substr(btrim(color),4,1)) ELSE lower(btrim(color)) END WHERE color IS NOT NULL;
ALTER TABLE "QuizPage" ADD CONSTRAINT "QuizPage_color_hex_check" CHECK (color IS NULL OR color ~ '^#[0-9a-f]{6}$');
UPDATE "Question" SET color = CASE WHEN color IS NULL OR btrim(color) = '' THEN NULL WHEN lower(btrim(color)) = 'blue' THEN '#3b82f6' WHEN lower(btrim(color)) = 'purple' THEN '#8b5cf6' WHEN lower(btrim(color)) = 'pink' THEN '#ec4899' WHEN lower(btrim(color)) = 'rose' THEN '#f43f5e' WHEN lower(btrim(color)) = 'orange' THEN '#f97316' WHEN lower(btrim(color)) = 'amber' THEN '#f59e42' WHEN lower(btrim(color)) = 'green' THEN '#22c55e' WHEN lower(btrim(color)) = 'teal' THEN '#14b8a6' WHEN lower(btrim(color)) = 'cyan' THEN '#06b6d4' WHEN lower(btrim(color)) = 'indigo' THEN '#6366f1' WHEN lower(btrim(color)) = 'violet' THEN '#a21caf' WHEN lower(btrim(color)) = 'fuchsia' THEN '#d946ef' WHEN btrim(color) ~ '^#[0-9a-fA-F]{3}$' THEN lower('#' || substr(btrim(color),2,1) || substr(btrim(color),2,1) || substr(btrim(color),3,1) || substr(btrim(color),3,1) || substr(btrim(color),4,1) || substr(btrim(color),4,1)) ELSE lower(btrim(color)) END WHERE color IS NOT NULL;
ALTER TABLE "Question" ADD CONSTRAINT "Question_color_hex_check" CHECK (color IS NULL OR color ~ '^#[0-9a-f]{6}$');
UPDATE "Answer" SET color = CASE WHEN color IS NULL OR btrim(color) = '' THEN NULL WHEN lower(btrim(color)) = 'blue' THEN '#3b82f6' WHEN lower(btrim(color)) = 'purple' THEN '#8b5cf6' WHEN lower(btrim(color)) = 'pink' THEN '#ec4899' WHEN lower(btrim(color)) = 'rose' THEN '#f43f5e' WHEN lower(btrim(color)) = 'orange' THEN '#f97316' WHEN lower(btrim(color)) = 'amber' THEN '#f59e42' WHEN lower(btrim(color)) = 'green' THEN '#22c55e' WHEN lower(btrim(color)) = 'teal' THEN '#14b8a6' WHEN lower(btrim(color)) = 'cyan' THEN '#06b6d4' WHEN lower(btrim(color)) = 'indigo' THEN '#6366f1' WHEN lower(btrim(color)) = 'violet' THEN '#a21caf' WHEN lower(btrim(color)) = 'fuchsia' THEN '#d946ef' WHEN btrim(color) ~ '^#[0-9a-fA-F]{3}$' THEN lower('#' || substr(btrim(color),2,1) || substr(btrim(color),2,1) || substr(btrim(color),3,1) || substr(btrim(color),3,1) || substr(btrim(color),4,1) || substr(btrim(color),4,1)) ELSE lower(btrim(color)) END WHERE color IS NOT NULL;
ALTER TABLE "Answer" ADD CONSTRAINT "Answer_color_hex_check" CHECK (color IS NULL OR color ~ '^#[0-9a-f]{6}$');

UPDATE "QuizResult" SET snapshot = jsonb_set(snapshot, '{archetype,color}', COALESCE(to_jsonb(CASE WHEN snapshot #>> '{archetype,color}' IS NULL OR btrim(snapshot #>> '{archetype,color}') = '' THEN NULL WHEN lower(btrim(snapshot #>> '{archetype,color}')) = 'blue' THEN '#3b82f6' WHEN lower(btrim(snapshot #>> '{archetype,color}')) = 'purple' THEN '#8b5cf6' WHEN lower(btrim(snapshot #>> '{archetype,color}')) = 'pink' THEN '#ec4899' WHEN lower(btrim(snapshot #>> '{archetype,color}')) = 'rose' THEN '#f43f5e' WHEN lower(btrim(snapshot #>> '{archetype,color}')) = 'orange' THEN '#f97316' WHEN lower(btrim(snapshot #>> '{archetype,color}')) = 'amber' THEN '#f59e42' WHEN lower(btrim(snapshot #>> '{archetype,color}')) = 'green' THEN '#22c55e' WHEN lower(btrim(snapshot #>> '{archetype,color}')) = 'teal' THEN '#14b8a6' WHEN lower(btrim(snapshot #>> '{archetype,color}')) = 'cyan' THEN '#06b6d4' WHEN lower(btrim(snapshot #>> '{archetype,color}')) = 'indigo' THEN '#6366f1' WHEN lower(btrim(snapshot #>> '{archetype,color}')) = 'violet' THEN '#a21caf' WHEN lower(btrim(snapshot #>> '{archetype,color}')) = 'fuchsia' THEN '#d946ef' WHEN btrim(snapshot #>> '{archetype,color}') ~ '^#[0-9a-fA-F]{3}$' THEN lower('#' || substr(btrim(snapshot #>> '{archetype,color}'),2,1) || substr(btrim(snapshot #>> '{archetype,color}'),2,1) || substr(btrim(snapshot #>> '{archetype,color}'),3,1) || substr(btrim(snapshot #>> '{archetype,color}'),3,1) || substr(btrim(snapshot #>> '{archetype,color}'),4,1) || substr(btrim(snapshot #>> '{archetype,color}'),4,1)) ELSE lower(btrim(snapshot #>> '{archetype,color}')) END), 'null'::jsonb)) WHERE jsonb_typeof(snapshot #> '{archetype,color}') = 'string';
COMMIT;
